once(function RES () {
    var cbs = reqs[key]
    var len = cbs.length
    var args = slice(arguments)
    var err = null
    for (var i = 0; i < len; i++) {
      try {
        cbs[i].apply(null, args)
      } catch(e) {
        err = e
      }
    }
    if (cbs.length > len) {
      // added more in the interim.
      // de-zalgo, just in case, but don't call again.
      cbs.splice(0, len)
      process.nextTick(function () {
        RES.apply(null, args)
      })
    } else {
      delete reqs[key]
    }
    if (err) {
      throw err
    }
  })

